import { posix } from "node:path";

import type { DoctorContext, FindingInput, Rule } from "./rules.ts";

import { PRESET_CATALOG } from "../../preset/index.ts";
import { resolveBlocks, splitStatements } from "../../sql/index.ts";

/** The first characters of a file `db seed --sample --out` wrote. */
export const SAMPLE_FILE_MARKER =
  "-- Generated by `better-supabase db seed --sample`";

/**
 * The installed modules that declare tenant defaults. A name that resolves to
 * no module (a block this release doesn't know) is skipped.
 */
function modulesWithDefaults(context: DoctorContext): readonly string[] {
  const names = context.config.blockNames.flatMap((name) => {
    try {
      return resolveBlocks([name], {});
    } catch {
      return [];
    }
  });

  return [
    ...new Set(
      names
        .filter((module) => module.seeds?.defaults !== undefined)
        .map((module) => module.name),
    ),
  ];
}

/** BS354: declared defaults that no organization receives. */
function defaultsNotApplied(context: DoctorContext): FindingInput[] {
  const declaring = modulesWithDefaults(context);

  if (declaring.length === 0) {
    return [];
  }

  const { defaults } = context.config.seed;
  const names = declaring.join(", ");

  if (!context.config.blockNames.includes("seeds")) {
    return [
      {
        message: `${names} declare tenant defaults, and the seeds block is not installed, so no organization receives them. Run better-supabase add seeds.`,
        target: "blocks.seeds",
      },
    ];
  }

  if (!defaults.enabled || !defaults.onCreate) {
    return [
      {
        message: `${names} declare tenant defaults, but database.seed.defaults ${defaults.enabled ? "has onCreate off" : "is false"}, so new organizations start without them. Turn it on, or run better-supabase db seed --defaults for each organization.`,
        target: "database.seed.defaults",
      },
    ];
  }

  if (!context.config.blockNames.includes("organizations")) {
    return [
      {
        message: `${names} declare tenant defaults, and the organizations block is not installed, so nothing calls them when an organization is created. Run better-supabase db seed --defaults for each organization.`,
        target: "blocks.organizations",
      },
    ];
  }

  return [];
}

/** BS355: a configured variant that its block does not declare. */
function undeclaredVariants(context: DoctorContext): FindingInput[] {
  return Object.entries(context.config.seed.defaults.variants).flatMap(
    ([block, variant]): FindingInput[] => {
      const target = `database.seed.defaults.variants.${block}`;
      const entry = PRESET_CATALOG.blocks.find((item) => item.name === block);

      if (entry === undefined) {
        return [
          {
            message: `database.seed.defaults.variants names "${block}", which is not a block.`,
            target,
          },
        ];
      }

      const offered = entry.seeds?.variants ?? [];

      if (offered.includes(variant)) {
        return [];
      }

      return [
        {
          message:
            offered.length === 0
              ? `database.seed.defaults.variants.${block} is "${variant}", but ${block} declares no variants.`
              : `database.seed.defaults.variants.${block} is "${variant}"; ${block} offers ${offered.join(", ")}.`,
          target,
        },
      ];
    },
  );
}

/** BS356: a generated sample file outside `database.seed.sample.output`. */
function sampleFileNotConfigured(context: DoctorContext): FindingInput[] {
  const configured = posix.normalize(context.config.seed.sample.file);

  return (context.seedFiles ?? [])
    .filter(
      (file) =>
        file.text.startsWith(SAMPLE_FILE_MARKER) &&
        posix.normalize(file.path) !== configured,
    )
    .map((file) => ({
      message: `${file.path} holds sample data from db seed --sample, and database.seed.sample.output is ${configured}. Set database.seed.sample.output to ${file.path} so the next run replaces it, and keep it out of production migrations.`,
      target: file.path,
    }));
}

const IDENT = String.raw`(?:"(?:[^"]|"")+"|[A-Za-z_][\w$]*)`;

const INSERT_TARGET = new RegExp(
  String.raw`^insert\s+into\s+(${IDENT}(?:\s*\.\s*${IDENT})?)`,
  "i",
);

const SEED_FUNCTION = new RegExp(
  String.raw`^create\s+(?:or\s+replace\s+)?function\s+(${IDENT}(?:\s*\.\s*${IDENT})?)\s*\(([^)]*)\)`,
  "i",
);

/** A table name without quotes, spaces and a default schema, to compare by. */
const tableKey = (name: string): string =>
  name
    .replaceAll(/["\s]/g, "")
    .toLowerCase()
    .replace(/^public\./, "");

const isDataFile = (file: { readonly text: string }): boolean =>
  file.text.includes("-- @bsb-block-data ");

/** The tables the insert statements of `files` write to, with their lines. */
function insertedTables(
  files: readonly { readonly path: string; readonly text: string }[],
): { path: string; table: string; line: number; text: string }[] {
  return files.flatMap((file) =>
    splitStatements(file.text).flatMap((statement) => {
      const match = INSERT_TARGET.exec(statement.text);

      return match === null
        ? []
        : [
            {
              path: file.path,
              table: tableKey(match[1]!),
              line: statement.line,
              text: statement.text,
            },
          ];
    }),
  );
}

/** BS357: an insert in a block data file that reruns without a key. */
function dataStatementWithoutKey(context: DoctorContext): FindingInput[] {
  return insertedTables((context.dataFiles ?? []).filter(isDataFile))
    .filter(
      (insert) =>
        !/\bon\s+conflict\b/i.test(insert.text) &&
        !/\bnot\s+exists\b/i.test(insert.text),
    )
    .map((insert) => ({
      message: `${insert.path}:${String(insert.line)}: this insert into ${insert.table} has no key, so a second run adds the rows again. End it with on conflict (...) do nothing or do update.`,
      target: insert.path,
      location: { file: insert.path, line: insert.line },
    }));
}

/** BS358: an app seed file that writes a table a block seeds. */
function appSeedOnBlockTable(context: DoctorContext): FindingInput[] {
  const blockTables = new Set(
    insertedTables((context.dataFiles ?? []).filter(isDataFile)).map(
      (insert) => insert.table,
    ),
  );

  if (blockTables.size === 0) {
    return [];
  }

  return insertedTables(
    (context.seedFiles ?? []).filter(
      (file) => !file.text.startsWith(SAMPLE_FILE_MARKER),
    ),
  )
    .filter((insert) => blockTables.has(insert.table))
    .map((insert) => ({
      message: `${insert.path}:${String(insert.line)}: ${insert.table} is seeded by a block data file, so the block and this file both own its rows. Seed it from one place.`,
      target: insert.path,
      location: { file: insert.path, line: insert.line },
    }));
}

/** BS359: a `seed_*_defaults` function that takes no locale. */
function seedFunctionWithoutLocale(context: DoctorContext): FindingInput[] {
  return (context.sqlFiles ?? [])
    .filter((file) => !/(?:^|\/)migrations\//.test(file.path))
    .flatMap((file) =>
      splitStatements(file.text).flatMap((statement): FindingInput[] => {
        const match = SEED_FUNCTION.exec(statement.text);

        if (match === null) {
          return [];
        }

        const name = match[1]!.split(".").at(-1)!.replaceAll('"', "").trim();

        return /^seed_.*_defaults$/.test(name) && !/locale/i.test(match[2]!)
          ? [
              {
                message: `${file.path}:${String(statement.line)}: ${name} takes no locale. Add p_locale text, so the rows can differ per country.`,
                target: file.path,
                location: { file: file.path, line: statement.line },
              },
            ]
          : [];
      }),
    );
}

/** Declared tenant defaults, sample files and data files (BS354 to BS359). */
export const SEED_RULES: readonly Rule[] = [
  {
    code: "BS354",
    severity: "warning",
    title: "Declared defaults are not applied to new organizations",
    description:
      "An installed block declares tenant defaults (`seeds.defaults`), but the `seeds` block is not installed, `database.seed.defaults` is off or has `onCreate: false`, or `organizations` is not installed, so the `after_organization_create` hook never calls `seed_tenant_defaults`. New organizations start without the defaults. Install `seeds`, turn the config key back on, or run `better-supabase db seed --defaults` for each organization.",
    check: defaultsNotApplied,
  },
  {
    code: "BS355",
    severity: "warning",
    title: "Seed variant is not declared",
    description:
      "`database.seed.defaults.variants` names a block that doesn't exist, or a variant the block doesn't declare. `better-supabase blocks` lists the variants each block offers. Use one of them or remove the entry.",
    check: undeclaredVariants,
  },
  {
    code: "BS356",
    severity: "info",
    title: "Sample data file outside database.seed.sample.output",
    description:
      "A file under `supabase/seeds` was written by `better-supabase db seed --sample --out`, but `database.seed.sample.output` points elsewhere. The next run writes a second copy instead of replacing it, and `supabase db reset` loads both. Set `database.seed.sample.output` to the file, or delete it.",
    check: sampleFileNotConfigured,
  },
  {
    code: "BS357",
    severity: "error",
    title: "A data file insert has no key",
    description:
      "A block data file reruns in every data migration that changes it, so each `insert` ends with `on conflict (...)` or guards itself with `not exists`. Without a key a second run adds the rows again. Reads the files in `supabase/better-supabase-data`.",
    check: dataStatementWithoutKey,
  },
  {
    code: "BS358",
    severity: "warning",
    title: "An app seed writes a table a block seeds",
    description:
      "A file under `supabase/seeds` inserts into a table that a block data file also inserts into. Both own the rows, so a reset and a data migration can disagree. Let the block seed the table, or keep the rows in your seed and remove the block's. Files `db seed --sample` wrote are left out.",
    check: appSeedOnBlockTable,
  },
  {
    code: "BS359",
    severity: "warning",
    title: "A seed function takes no locale",
    description:
      "A function named `seed_<name>_defaults` has no `p_locale` parameter. Defaults that depend on a country (tax codes, letterheads, number formats) need the locale, and `seed_tenant_defaults` passes it to every seed function. Reads every schema file.",
    check: seedFunctionWithoutLocale,
  },
];
